///
/// plIndex used to print pl->client->pers.netname; teamIndex used to print
/// team name.
/// Source: `oracle/oracle/codemp/game/g_team.c:100-132`
pub fn PrintCTFMessage(
    ctx: GameContext<'_>,
    plIndex: c_int,
    teamIndex: c_int,
    ctfMessage: c_int,
) {
    // MAX_CLIENTS not threaded through this packet's resolved surface; use
    // the Raven literal directly (g_team.c:106 hardcodes the same +1 idiom).
    let plIndex = if plIndex == -1 { 32 + 1 } else { plIndex };
    let teamIndex = if teamIndex == -1 { 50 } else { teamIndex };

    unsafe {
        let te = G_TempEntity(ctx, [0.0, 0.0, 0.0], entity_event_t::EV_CTFMESSAGE as c_int);
        (*te).r.svFlags |= SVF_BROADCAST;
        (*te).s.eventParm = ctfMessage;
        (*te).s.trickedentindex = plIndex;
        if ctfMessage == ctfMsg_t::CTFMESSAGE_PLAYER_CAPTURED_FLAG as c_int {
            (*te).s.trickedentindex2 = if teamIndex == TEAM_RED { TEAM_BLUE } else { TEAM_RED };
        } else {
            (*te).s.trickedentindex2 = teamIndex;
        }
    }
}

/// Raven `AddTeamScore`.
///
/// Source: `oracle/oracle/codemp/game/g_team.c:142-179`
pub fn AddTeamScore(
    ctx: GameContext<'_>,
    origin: vec3_t,
    team: c_int,
    score: c_int,
) {
    unsafe {
        let te = G_TempEntity(ctx, origin, entity_event_t::EV_GLOBAL_TEAM_SOUND as c_int);
        (*te).r.svFlags |= SVF_BROADCAST;

        let world = &mut *ctx.world;

        if team == TEAM_RED {
            if world.level.teamScores[TEAM_RED as usize] + score == world.level.teamScores[TEAM_BLUE as usize] {
                (*te).s.eventParm = global_team_sound_t::GTS_TEAMS_ARE_TIED as c_int;
            } else if world.level.teamScores[TEAM_RED as usize] <= world.level.teamScores[TEAM_BLUE as usize]
                && world.level.teamScores[TEAM_RED as usize] + score > world.level.teamScores[TEAM_BLUE as usize]
            {
                (*te).s.eventParm = global_team_sound_t::GTS_REDTEAM_TOOK_LEAD as c_int;
            } else {
                (*te).s.eventParm = global_team_sound_t::GTS_REDTEAM_SCORED as c_int;
            }
        } else {
            if world.level.teamScores[TEAM_BLUE as usize] + score == world.level.teamScores[TEAM_RED as usize] {
                (*te).s.eventParm = global_team_sound_t::GTS_TEAMS_ARE_TIED as c_int;
            } else if world.level.teamScores[TEAM_BLUE as usize] <= world.level.teamScores[TEAM_RED as usize]
                && world.level.teamScores[TEAM_BLUE as usize] + score > world.level.teamScores[TEAM_RED as usize]
            {
                (*te).s.eventParm = global_team_sound_t::GTS_BLUETEAM_TOOK_LEAD as c_int;
            } else {
                (*te).s.eventParm = global_team_sound_t::GTS_BLUETEAM_SCORED as c_int;
            }
        }

        world.level.teamScores[team as usize] += score;
    }
}

/// Raven `OnSameTeam`.
///
/// Source: `oracle/oracle/codemp/game/g_team.c:187-276`
pub fn OnSameTeam(
    ctx: GameContext<'_>,
    ent1: *mut gentity_t,
    ent2: *mut gentity_t,
) -> qboolean {
    unsafe {
        if (*ent1).client.is_null() || (*ent2).client.is_null() {
            return qfalse;
        }

        let world = &*ctx.world;
        let gametype = world.cvars.g_gametype.integer;

        if gametype == GT_POWERDUEL as c_int {
            if (*((*ent1).client as *mut gclient_t)).sess.duelTeam == (*((*ent2).client as *mut gclient_t)).sess.duelTeam {
                return qtrue;
            }
            return qfalse;
        }

        if gametype == GT_SINGLE_PLAYER as c_int {
            let ent1IsBot =
                if (*ent1).r.svFlags & 0x0001 != 0 { qtrue } else { qfalse };
            let ent2IsBot =
                if (*ent2).r.svFlags & 0x0001 != 0 { qtrue } else { qfalse };

            if (ent1IsBot != 0 && ent2IsBot != 0) || (ent1IsBot == 0 && ent2IsBot == 0) {
                return qtrue;
            }
            return qfalse;
        }

        if gametype < GT_TEAM as c_int {
            return qfalse;
        }

        if (*ent1).s.eType == entityType_t::ET_NPC as c_int
            && (*ent1).s.NPC_class as c_int == 130 // CLASS_VEHICLE
            && !(*ent1).client.is_null()
            && (*((*ent1).client as *mut gclient_t)).sess.sessionTeam as c_int != TEAM_FREE
            && !(*ent2).client.is_null()
            && (*((*ent1).client as *mut gclient_t)).sess.sessionTeam as c_int == (*((*ent2).client as *mut gclient_t)).sess.sessionTeam as c_int
        {
            return qtrue;
        }
        if (*ent2).s.eType == entityType_t::ET_NPC as c_int
            && (*ent2).s.NPC_class as c_int == 130 // CLASS_VEHICLE
            && !(*ent2).client.is_null()
            && (*((*ent2).client as *mut gclient_t)).sess.sessionTeam as c_int != TEAM_FREE
            && !(*ent1).client.is_null()
            && (*((*ent2).client as *mut gclient_t)).sess.sessionTeam as c_int == (*((*ent1).client as *mut gclient_t)).sess.sessionTeam as c_int
        {
            return qtrue;
        }

        if (*((*ent1).client as *mut gclient_t)).sess.sessionTeam as c_int == TEAM_FREE
            && (*((*ent2).client as *mut gclient_t)).sess.sessionTeam as c_int == TEAM_FREE
            && (*ent1).s.eType == entityType_t::ET_NPC as c_int
            && (*ent2).s.eType == entityType_t::ET_NPC as c_int
        {
            return qfalse;
        }

        if (*ent1).s.eType == entityType_t::ET_NPC as c_int
            && (*ent2).s.eType == entityType_t::ET_PLAYER as c_int
        {
            if G_CheckVehicleNPCTeamDamage(ent1) != 0 {
                if (*((*ent1).client as *mut gclient_t)).sess.sessionTeam as c_int == (*((*ent2).client as *mut gclient_t)).sess.sessionTeam as c_int
                    || (*ent1).teamnodmg == (*((*ent2).client as *mut gclient_t)).sess.sessionTeam as c_int
                {
                    return qtrue;
                }
            }
            return qfalse;
        } else if (*ent1).s.eType == entityType_t::ET_PLAYER as c_int
            && (*ent2).s.eType == entityType_t::ET_NPC as c_int
        {
            return qfalse;
        }

        if (*((*ent1).client as *mut gclient_t)).sess.sessionTeam as c_int == (*((*ent2).client as *mut gclient_t)).sess.sessionTeam as c_int {
            return qtrue;
        }

        qfalse
    }
}

/// Raven `Team_SetFlagStatus`.
///
/// Source: `oracle/oracle/codemp/game/g_team.c:281-318`
pub fn Team_SetFlagStatus(
    ctx: GameContext<'_>,
    team: c_int,
    status: flagStatus_t,
) {
    unsafe {
        let world = &mut *ctx.world;
        let mut modified = qfalse;

        match team {
            TEAM_RED => {
                if world.globals.teamgame.redStatus != status {
                    world.globals.teamgame.redStatus = status;
                    modified = qtrue;
                }
            }
            TEAM_BLUE => {
                if world.globals.teamgame.blueStatus != status {
                    world.globals.teamgame.blueStatus = status;
                    modified = qtrue;
                }
            }
            TEAM_FREE => {
                if world.globals.teamgame.flagStatus != status {
                    world.globals.teamgame.flagStatus = status;
                    modified = qtrue;
                }
            }
            _ => {}
        }

        if modified != 0 {
            let ctfFlagStatusRemap: &[u8] = &[b'0', b'1', b'*', b'*', b'2'];
            let mut st: [c_char; 4] = [0; 4];

            if world.cvars.g_gametype.integer == GT_CTF as c_int
                || world.cvars.g_gametype.integer == GT_CTY as c_int
            {
                st[0] = ctfFlagStatusRemap[world.globals.teamgame.redStatus as usize] as c_char;
                st[1] = ctfFlagStatusRemap[world.globals.teamgame.blueStatus as usize] as c_char;
                st[2] = 0;
            }

            trap::SetConfigstring(ctx.engine, 6, st.as_ptr());
        }
    }
}

/// Raven `Team_CheckDroppedItem`.
///
/// Source: `oracle/oracle/codemp/game/g_team.c:320-330`
pub fn Team_CheckDroppedItem(
    ctx: GameContext<'_>,
    dropped: *mut gentity_t,
) {
    unsafe {
        let giTag = (*(*dropped).item).giTag;
        if giTag == PW_REDFLAG {
            Team_SetFlagStatus(ctx, TEAM_RED, FLAG_DROPPED);
        } else if giTag == PW_BLUEFLAG {
            Team_SetFlagStatus(ctx, TEAM_BLUE, FLAG_DROPPED);
        } else if giTag == PW_NEUTRALFLAG {
            Team_SetFlagStatus(ctx, TEAM_FREE, FLAG_DROPPED);
        }
    }
}

/// Raven `Team_ForceGesture`.
///
/// Source: `oracle/oracle/codemp/game/g_team.c:337-352`
pub fn Team_ForceGesture(
    ctx: GameContext<'_>,
    team: c_int,
) {
    unsafe {
        let world = &mut *ctx.world;
        let max_clients = world.cvars.g_maxclients.integer;

        for i in 0..max_clients {
            let ent = &mut world.g_entities[i as usize];
            if (*ent).inuse == 0 {
                continue;
            }
            if (*ent).client.is_null() {
                continue;
            }
            if (*((*ent).client as *mut gclient_t)).sess.sessionTeam as c_int != team {
                continue;
            }

            (*ent).flags |= FL_FORCE_GESTURE;
        }
    }
}

/// Raven `Team_FragBonuses`.
///
/// Source: `oracle/oracle/codemp/game/g_team.c:363-534`
pub fn Team_FragBonuses(
    ctx: GameContext<'_>,
    targ: *mut gentity_t,
    inflictor: *mut gentity_t,
    attacker: *mut gentity_t,
) {
    unsafe {
        // no bonus for fragging yourself or team mates
        if (*targ).client.is_null() || (*attacker).client.is_null() || targ == attacker
            || OnSameTeam(ctx, targ, attacker) != 0
        {
            return;
        }

        let world = &mut *ctx.world;
        let team = (*((*targ).client as *mut gclient_t)).sess.sessionTeam as c_int;
        let otherteam = OtherTeam(team);
        if otherteam < 0 {
            return; // whoever died isn't on a team
        }

        // same team, if the flag at base, check to he has the enemy flag
        let (flag_pw, enemy_flag_pw) = if team == TEAM_RED {
            (PW_REDFLAG, PW_BLUEFLAG)
        } else {
            (PW_BLUEFLAG, PW_REDFLAG)
        };

        // did the attacker frag the flag carrier?
        if (*((*targ).client as *mut gclient_t)).ps.powerups[enemy_flag_pw as usize] != 0 {
            (*((*attacker).client as *mut gclient_t)).pers.teamState.lastfraggedcarrier = world.level.time;
            // AddScore(attacker, targ->r.currentOrigin, CTF_FRAG_CARRIER_BONUS);
            (*((*attacker).client as *mut gclient_t)).pers.teamState.fragcarrier += 1;
            PrintCTFMessage((*attacker).s.number, team, ctfMsg_t::CTFMESSAGE_FRAGGED_FLAG_CARRIER as c_int);

            // the target had the flag, clear the hurt carrier field on the other team
            let max_clients = world.cvars.g_maxclients.integer;
            for i in 0..max_clients {
                let ent = &mut world.g_entities[i as usize];
                if (*ent).inuse != 0 && (*((*ent).client as *mut gclient_t)).sess.sessionTeam as c_int == otherteam {
                    (*((*ent).client as *mut gclient_t)).pers.teamState.lasthurtcarrier = 0;
                }
            }
            return;
        }

        // did the attacker frag a head carrier? other->client->ps.generic1
        if (*((*targ).client as *mut gclient_t)).ps.generic1 != 0 {
            (*((*attacker).client as *mut gclient_t)).pers.teamState.lastfraggedcarrier = world.level.time;
            // AddScore(attacker, targ->r.currentOrigin, CTF_FRAG_CARRIER_BONUS * tokens * tokens);
            (*((*attacker).client as *mut gclient_t)).pers.teamState.fragcarrier += 1;

            // the target had the flag, clear the hurt carrier field on the other team
            let max_clients = world.cvars.g_maxclients.integer;
            for i in 0..max_clients {
                let ent = &mut world.g_entities[i as usize];
                if (*ent).inuse != 0 && (*((*ent).client as *mut gclient_t)).sess.sessionTeam as c_int == otherteam {
                    (*((*ent).client as *mut gclient_t)).pers.teamState.lasthurtcarrier = 0;
                }
            }
            return;
        }

        if (*((*targ).client as *mut gclient_t)).pers.teamState.lasthurtcarrier != 0
            && world.level.time - (*((*targ).client as *mut gclient_t)).pers.teamState.lasthurtcarrier < 10000
            && (*((*attacker).client as *mut gclient_t)).ps.powerups[flag_pw as usize] == 0
        {
            // attacker is on the same team as the flag carrier and fragged a guy who hurt our flag carrier
            // AddScore(attacker, targ->r.currentOrigin, CTF_CARRIER_DANGER_PROTECT_BONUS);

            (*((*attacker).client as *mut gclient_t)).pers.teamState.carrierdefense += 1;
            (*((*targ).client as *mut gclient_t)).pers.teamState.lasthurtcarrier = 0;

            (*((*attacker).client as *mut gclient_t)).ps.persistant[persEnum_t::PERS_DEFEND_COUNT as usize] += 1;
            let _team = (*((*attacker).client as *mut gclient_t)).sess.sessionTeam as c_int;
            (*((*attacker).client as *mut gclient_t)).rewardTime = world.level.time + 2000;

            return;
        }

        if (*((*targ).client as *mut gclient_t)).pers.teamState.lasthurtcarrier != 0
            && world.level.time - (*((*targ).client as *mut gclient_t)).pers.teamState.lasthurtcarrier < 10000
        {
            // attacker is on the same team as the skull carrier and
            // AddScore(attacker, targ->r.currentOrigin, CTF_CARRIER_DANGER_PROTECT_BONUS);

            (*((*attacker).client as *mut gclient_t)).pers.teamState.carrierdefense += 1;
            (*((*targ).client as *mut gclient_t)).pers.teamState.lasthurtcarrier = 0;

            (*((*attacker).client as *mut gclient_t)).ps.persistant[persEnum_t::PERS_DEFEND_COUNT as usize] += 1;
            let _team = (*((*attacker).client as *mut gclient_t)).sess.sessionTeam as c_int;
            (*((*attacker).client as *mut gclient_t)).rewardTime = world.level.time + 2000;

            return;
        }

        // flag and flag carrier area defense bonuses

        // we have to find the flag and carrier entities

        // find the flag
        let c = if (*((*attacker).client as *mut gclient_t)).sess.sessionTeam as c_int == TEAM_RED {
            c"team_CTF_redflag"
        } else if (*((*attacker).client as *mut gclient_t)).sess.sessionTeam as c_int == TEAM_BLUE {
            c"team_CTF_blueflag"
        } else {
            return;
        };

        // find attacker's team's flag carrier
        let mut carrier: *mut gentity_t = core::ptr::null_mut();
        let max_clients = world.cvars.g_maxclients.integer;
        for i in 0..max_clients {
            carrier = &mut world.g_entities[i as usize];
            if (*carrier).inuse != 0 && (*((*carrier).client as *mut gclient_t)).ps.powerups[flag_pw as usize] != 0 {
                break;
            }
            carrier = core::ptr::null_mut();
        }

        let mut flag: *mut gentity_t = core::ptr::null_mut();
        loop {
            flag = G_Find(ctx, flag, fofs_classname(), c.as_ptr());
            if flag.is_null() {
                break;
            }
            if (*flag).flags & FL_DROPPED_ITEM == 0 {
                break;
            }
        }

        if flag.is_null() {
            return; // can't find attacker's flag
        }

        // ok we have the attackers flag and a pointer to the carrier

        // check to see if we are defending the base's flag
        let mut v1 = [0.0f32; 3];
        let mut v2 = [0.0f32; 3];
        v1[0] = (*targ).r.currentOrigin[0] - (*flag).r.currentOrigin[0];
        v1[1] = (*targ).r.currentOrigin[1] - (*flag).r.currentOrigin[1];
        v1[2] = (*targ).r.currentOrigin[2] - (*flag).r.currentOrigin[2];
        v2[0] = (*attacker).r.currentOrigin[0] - (*flag).r.currentOrigin[0];
        v2[1] = (*attacker).r.currentOrigin[1] - (*flag).r.currentOrigin[1];
        v2[2] = (*attacker).r.currentOrigin[2] - (*flag).r.currentOrigin[2];

        let v1_len = (v1[0] * v1[0] + v1[1] * v1[1] + v1[2] * v1[2]).sqrt();
        let v2_len = (v2[0] * v2[0] + v2[1] * v2[1] + v2[2] * v2[2]).sqrt();

        if ((v1_len < 500.0 && trap::InPVS(ctx.engine, (*flag).r.currentOrigin.as_ptr(), (*targ).r.currentOrigin.as_ptr()) != 0)
            || (v2_len < 500.0 && trap::InPVS(ctx.engine, (*flag).r.currentOrigin.as_ptr(), (*attacker).r.currentOrigin.as_ptr()) != 0))
            && (*((*attacker).client as *mut gclient_t)).sess.sessionTeam as c_int != (*((*targ).client as *mut gclient_t)).sess.sessionTeam as c_int
        {
            // we defended the base flag
            // AddScore(attacker, targ->r.currentOrigin, CTF_FLAG_DEFENSE_BONUS);
            (*((*attacker).client as *mut gclient_t)).pers.teamState.basedefense += 1;

            (*((*attacker).client as *mut gclient_t)).ps.persistant[persEnum_t::PERS_DEFEND_COUNT as usize] += 1;
            (*((*attacker).client as *mut gclient_t)).rewardTime = world.level.time + 2000;

            return;
        }

        if !carrier.is_null() && carrier != attacker {
            v1[0] = (*targ).r.currentOrigin[0] - (*carrier).r.currentOrigin[0];
            v1[1] = (*targ).r.currentOrigin[1] - (*carrier).r.currentOrigin[1];
            v1[2] = (*targ).r.currentOrigin[2] - (*carrier).r.currentOrigin[2];
            v2[0] = (*attacker).r.currentOrigin[0] - (*carrier).r.currentOrigin[0];
            v2[1] = (*attacker).r.currentOrigin[1] - (*carrier).r.currentOrigin[1];
            v2[2] = (*attacker).r.currentOrigin[2] - (*carrier).r.currentOrigin[2];

            let v1_len = (v1[0] * v1[0] + v1[1] * v1[1] + v1[2] * v1[2]).sqrt();
            let v2_len = (v2[0] * v2[0] + v2[1] * v2[1] + v2[2] * v2[2]).sqrt();

            if ((v1_len < 300.0 && trap::InPVS(ctx.engine, (*carrier).r.currentOrigin.as_ptr(), (*targ).r.currentOrigin.as_ptr()) != 0)
                || (v2_len < 300.0 && trap::InPVS(ctx.engine, (*carrier).r.currentOrigin.as_ptr(), (*attacker).r.currentOrigin.as_ptr()) != 0))
                && (*((*attacker).client as *mut gclient_t)).sess.sessionTeam as c_int != (*((*targ).client as *mut gclient_t)).sess.sessionTeam as c_int
            {
                // AddScore(attacker, targ->r.currentOrigin, CTF_CARRIER_PROTECT_BONUS);
                (*((*attacker).client as *mut gclient_t)).pers.teamState.carrierdefense += 1;

                (*((*attacker).client as *mut gclient_t)).ps.persistant[persEnum_t::PERS_DEFEND_COUNT as usize] += 1;
                (*((*attacker).client as *mut gclient_t)).rewardTime = world.level.time + 2000;

                return;
            }
        }
    }
}

/// Raven `Team_CheckHurtCarrier`.
///
/// Source: `oracle/oracle/codemp/game/g_team.c:544-565`
pub fn Team_CheckHurtCarrier(
    ctx: GameContext<'_>,
    targ: *mut gentity_t,
    attacker: *mut gentity_t,
) {
    unsafe {
        if (*targ).client.is_null() || (*attacker).client.is_null() {
            return;
        }

        let flag_pw = if (*((*targ).client as *mut gclient_t)).sess.sessionTeam as c_int == TEAM_RED {
            PW_BLUEFLAG
        } else {
            PW_REDFLAG
        };

        let world = &mut *ctx.world;
        // flags
        if (*((*targ).client as *mut gclient_t)).ps.powerups[flag_pw as usize] != 0
            && (*((*targ).client as *mut gclient_t)).sess.sessionTeam as c_int != (*((*attacker).client as *mut gclient_t)).sess.sessionTeam as c_int
        {
            (*((*attacker).client as *mut gclient_t)).pers.teamState.lasthurtcarrier = world.level.time;
        }

        // skulls
        if (*((*targ).client as *mut gclient_t)).ps.generic1 != 0
            && (*((*targ).client as *mut gclient_t)).sess.sessionTeam as c_int != (*((*attacker).client as *mut gclient_t)).sess.sessionTeam as c_int
        {
            (*((*attacker).client as *mut gclient_t)).pers.teamState.lasthurtcarrier = world.level.time;
        }
    }
}

/// Raven `Team_ResetFlag`.
///
/// Source: `oracle/oracle/codemp/game/g_team.c:568-599`
pub fn Team_ResetFlag(
    ctx: GameContext<'_>,
    team: c_int,
) -> *mut gentity_t {
    let classname: &CStr = if team == TEAM_RED {
        c"team_CTF_redflag"
    } else if team == TEAM_BLUE {
        c"team_CTF_blueflag"
    } else if team == TEAM_FREE {
        c"team_CTF_neutralflag"
    } else {
        return core::ptr::null_mut();
    };

    unsafe {
        let mut ent: *mut gentity_t = core::ptr::null_mut();
        let mut rent: *mut gentity_t = core::ptr::null_mut();
        loop {
            ent = G_Find(ctx, ent, fofs_classname(), classname.as_ptr());
            if ent.is_null() {
                break;
            }
            if (*ent).flags & FL_DROPPED_ITEM != 0 {
                G_FreeEntity(ctx, ent);
            } else {
                rent = ent;
                RespawnItem(ctx, ent);
            }
        }

        Team_SetFlagStatus(ctx, team, FLAG_ATBASE);

        rent
    }
}

/// Raven `Team_ResetFlags`.
///
